                if expr[j] == "\\" and j+1 < n:
                    out += expr[j] + expr[j+1]
                    j += 2
                elif expr[j] == quote:
                    out += quote
                    j += 1
                    break
                else:
                    out += expr[j]
                    j += 1
            tokens.append(out)
            i = j
        else:
            j = i
            while j < n and not expr[j].isspace():
                j += 1
            tokens.append(expr[i:j])
