    # Command
    cmd_flags = COMMAND_FLAGS.get(effective_cmd, {})
    for name, spec in cmd_flags.items():
        specs[spec["long"]] = {"name": name, "type": spec["type"], "is_global": False, "short": spec["short"], "default": spec.get("default"), "required": spec.get("required", False)}
