def get_ordered_shorts(cmd_name):
    # Return ordered list of short flags for suggestions (as observed)
    # Global first: -h, -W
    # Then command-specific in help order
    base = ["-h", "-W"]
    if cmd_name in (None, "init", "lsp"):
        return base
    if cmd_name == "index":
        return base + ["-f", "-v", "-q"]
    if cmd_name == "new":
        return base + ["-i", "-t", "-g", "-p", "-n"]
    if cmd_name == "list":
        return base + ["-f", "-d", "-0", "-P", "-q", "-i", "-n", "-m", "-M", "-x", "-t", "-l", "-L", "-r", "-s", "-e"]
    if cmd_name == "graph":
        return base + ["-f", "-q", "-i", "-n", "-m", "-M", "-x", "-t", "-l", "-L", "-r", "-s", "-e"]
    if cmd_name == "edit":
        return base + ["-f", "-i", "-n", "-m", "-M", "-x", "-t", "-l", "-L", "-r", "-s", "-e"]
    if cmd_name == "tag":
        return base + ["-f", "-d", "-0", "-P", "-q", "-s"]
    return base

